// Shared library for the REA_17 test harness: station + pack loaders, the
// input packs per axis (REA_17 §2), the field registry (one entry per §3
// card family), and the gate (mechanical · within-cell four-gram · reader
// zone). Nothing here writes to the station.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

export const HERE = path.dirname(fileURLToPath(import.meta.url));
export const ROOT = path.resolve(HERE, '../../../../') + '/';
export const S = ROOT + 'Reading/Database/templates/by_axis/json/';
export const OUT = HERE + '/out/';
export const REA17_PATH = ROOT + 'Reading/Documents/REA_17_Generation_Prompt_Pack.md';
export const REA16_PATH = ROOT + 'Reading/Documents/REA_16_The_Voice.md';

// ── station ──────────────────────────────────────────────────────────
export const strip = (o) => Array.isArray(o) ? o.map(strip) : (o && typeof o === 'object') ? Object.fromEntries(Object.keys(o).filter((k) => !k.startsWith('__ore')).map((k) => [k, strip(o[k])])) : o;
export const J = (p) => strip(JSON.parse(fs.readFileSync(S + p, 'utf8')).candidates);
export const exists = (p) => fs.existsSync(S + p);
export const wc = (s) => String(s || '').trim().split(/\s+/).filter(Boolean).length;
export const flat = (v, prefix = '') => typeof v === 'string' ? [[prefix, v]] : Array.isArray(v) ? v.flatMap((x, i) => flat(x, `${prefix}[${i}]`)) : (v && typeof v === 'object') ? Object.entries(v).flatMap(([k, x]) => flat(x, prefix ? `${prefix}.${k}` : k)) : [];
export const get = (o, p) => p.split('.').reduce((v, k) => v?.[k], o);

// ── the pack (REA_17) ────────────────────────────────────────────────
export const rea17 = fs.readFileSync(REA17_PATH, 'utf8');
export const rea17Version = (rea17.match(/\*\*Version\*\* \| ([0-9.]+)/) || [])[1] || '?';
const section = (from, to) => { const a = rea17.indexOf(from); if (a < 0) throw new Error('REA_17 section missing: ' + from); const b = rea17.indexOf(to, a + 1); return rea17.slice(a, b < 0 ? undefined : b); };
export const master = section('## §1 · THE MASTER PROMPT', '## §2 ·').split('\n').map((l) => l.replace(/^> ?/, '')).join('\n');
export const inputPackGeneral = section('## §2 · THE INPUT PACK', '## §3 ·');
export const card = (key) => { const a = rea17.indexOf('**`' + key + '`'); if (a < 0) throw new Error('REA_17 has no card ' + key); let b = rea17.indexOf('\n**`', a + 1); const c = rea17.indexOf('\n### ', a + 1); if (c > 0 && (b < 0 || c < b)) b = c; return rea17.slice(a, b < 0 ? undefined : b).trim(); };

// ── elements, stems, gods ────────────────────────────────────────────
export const HZ = { Wood: '木', Fire: '火', Earth: '土', Metal: '金', Water: '水' };
export const EL_OF_HZ = Object.fromEntries(Object.entries(HZ).map(([k, v]) => [v, k]));
export const FEED = { Wood: 'Fire', Fire: 'Earth', Earth: 'Metal', Metal: 'Water', Water: 'Wood' };
export const TAME = { Wood: 'Earth', Earth: 'Water', Water: 'Fire', Fire: 'Metal', Metal: 'Wood' };
export const ARENA = { Wood: 'Wood (trunk, branch, root, grain, growth, the forest)', Fire: 'Fire (flame, light, warmth, fuel, the hearth, the blaze)', Earth: 'Earth (ground, soil, load, field, bedrock, harvest)', Metal: 'Metal (edge, blade, ore, forge, whetstone, the clean line)', Water: 'Water (depth, current, tide, rain, spring, flow)' };
const IMAGE = { '木生火': 'dry branches make the flame', '火生土': 'ash becomes soil', '土生金': 'ore grows in the mountain', '金生水': 'dew beads on the cold blade', '水生木': 'rain raises the forest', '木克土': 'roots hold the hillside', '土克水': 'banks give the river its path', '水克火': 'rain ends the blaze', '火克金': 'the forge softens the blade', '金克木': 'the knife prunes the branch' };
export const relation = (core, energy) => core === energy ? ['self', 'Body'] : FEED[energy] === core ? ['feeder', 'Mind'] : FEED[core] === energy ? ['fed', 'Expression'] : TAME[core] === energy ? ['tamed', 'Action'] : ['tamer', 'Order'];
const law = (a, b) => FEED[a] === b ? `${a} feeds ${b} (${HZ[a]}生${HZ[b]}: ${IMAGE[HZ[a] + '生' + HZ[b]]})` : TAME[a] === b ? `${a} tames ${b} (${HZ[a]}克${HZ[b]}: ${IMAGE[HZ[a] + '克' + HZ[b]]})` : null;
export const pairLaw = (core, energy) => { const [rel, fn] = relation(core, energy); const l = law(energy, core) || law(core, energy) || `${core} and ${energy} are the same element (the self pair)`; return `Core element ${core}, energy element ${energy}. Law: ${l}. Relative to the core the energy is the ${rel}, so ${energy} is this core's ${fn}.`; };
// The five 渊海子平 excess sets (REA_17 §2.3, verbatim), keyed core_energy.
export const EXCESS_IDIOM = {
  '金_土': '金赖土生，土多金埋 (生之太过, the Mind door; 土多金埋 applies to 辛, 庚 reads 郁滞)', '土_火': '土赖火生，火多土焦 (生之太过, the Mind door)', '火_木': '火赖木生，木多火炽 (生之太过, the Mind door; read literally since D1: the fire blazes past its task)', '木_水': '木赖水生，水多木漂 (生之太过, the Mind door)', '水_金': '水赖金生，金多水浊 (生之太过, the Mind door)',
  '金_水': '金能生水，水多金沉 (泄之太过, the Expression door)', '水_木': '水能生木，木盛水缩 (泄之太过, the Expression door)', '木_火': '木能生火，火多木焚 (泄之太过, the Expression door)', '火_土': '火能生土，土多火晦 (泄之太过, the Expression door)', '土_金': '土能生金，金多土变 (泄之太过, the Expression door)',
  '金_木': '金能克木，木坚金缺 (克之不逮, the Action door)', '木_土': '木能克土，土重木折 (克之不逮, the Action door)', '土_水': '土能克水，水多土流 (克之不逮, the Action door)', '水_火': '水能克火，火多水热 (克之不逮, the Action door)', '火_金': '火能克金，金多火熄 (克之不逮, the Action door)',
  '金_火': '金衰遇火，必见销熔 (衰而逢克, the Order door)', '火_水': '火弱逢水，必为熄灭 (衰而逢克, the Order door)', '水_土': '水弱逢土，必为淤塞 (衰而逢克, the Order door)', '土_木': '土衰遇木，必遭倾陷 (衰而逢克, the Order door)', '木_金': '木弱逢金，必为砍折 (衰而逢克, the Order door)',
  '金_金': '强金得水，方挫其锋 (强而得制, the self pair)', '水_水': '强水得木，方泄其势 (强而得制, the self pair)', '木_木': '强木得火，方化其顽 (强而得制, the self pair)', '火_火': '强火得土，方止其焰 (强而得制, the self pair)', '土_土': '强土得金，方制其害 (强而得制, the self pair)',
};
export const WIDE_OPENERS = ['{Element} is one thing you never run short of', '{Element} is easy for you to reach', '{Element} is all around you', 'You have plenty of {Element}', '{Element} is already here in plenty', 'You are well supplied with {Element}', 'You were given plenty of {Element}', 'There is no shortage of {Element} in you'];
export const STEMS = {
  '甲': { file: 'jia', el: 'Wood', pol: 'yang', name: 'The Oak', spine: 'rises' }, '乙': { file: 'yi', el: 'Wood', pol: 'yin', name: 'The Vine', spine: 'routes' },
  '丙': { file: 'bing', el: 'Fire', pol: 'yang', name: 'The Sun', spine: 'radiates' }, '丁': { file: 'ding', el: 'Fire', pol: 'yin', name: 'The Candle', spine: 'concentrates' },
  '戊': { file: 'wu', el: 'Earth', pol: 'yang', name: 'The Mountain', spine: 'holds' }, '己': { file: 'ji', el: 'Earth', pol: 'yin', name: 'The Field', spine: 'receives and grows' },
  '庚': { file: 'geng', el: 'Metal', pol: 'yang', name: 'The Blade', spine: 'cuts' }, '辛': { file: 'xin', el: 'Metal', pol: 'yin', name: 'The Jewel', spine: 'refines' },
  '壬': { file: 'ren', el: 'Water', pol: 'yang', name: 'The Ocean', spine: 'ranges' }, '癸': { file: 'gui', el: 'Water', pol: 'yin', name: 'The Rain', spine: 'permeates' },
};
export const STEM_OF_FILE = Object.fromEntries(Object.entries(STEMS).map(([k, v]) => [v.file, k]));
// The neighbouring angle a stem must not borrow, where REA_17 §2.2 states it;
// every other stem gets the master prompt's own line (the two drifts).
const NOT_BORROW = { '癸': 'not depletion or unrecognised giving, that is 丙\'s and 己\'s', '壬': 'not neglect', '辛': 'not 庚\'s isolation' };
const angleRow = (stem) => { const m = master.match(new RegExp(`^\\| ${stem} [^\\n]*$`, 'm')); return m ? m[0] : ''; };
export const YIN_NOUNS = { '辛': 'stone, facet, setting, wheel (the Jewel for the Blade\'s shared line)', '乙': 'vine, wall, tendril (the Vine for the Oak\'s shared line)', '丁': 'the close flame, the table, the lamp (the Candle for the Sun\'s shared line)', '己': 'soil, field (the Field for the Mountain\'s shared line)', '癸': 'rain, mist, cloud (the Rain for the Ocean\'s shared line)' };
export const GOD_FILE = { '比肩': 'bijian', '劫财': 'jiecai', '食神': 'shishen', '伤官': 'shangguan', '偏财': 'piancai', '正财': 'zhengcai', '七杀': 'qisha', '正官': 'zhengguan', '偏印': 'pianyin', '正印': 'zhengyin' };
export const GOD_OF_FILE = Object.fromEntries(Object.entries(GOD_FILE).map(([k, v]) => [v, k]));
export const SIB = { '比肩': '劫财', '劫财': '比肩', '食神': '伤官', '伤官': '食神', '偏财': '正财', '正财': '偏财', '七杀': '正官', '正官': '七杀', '偏印': '正印', '正印': '偏印' };
export const FAMILY_FN = { '比肩': 'Body', '劫财': 'Body', '食神': 'Expression', '伤官': 'Expression', '偏财': 'Action', '正财': 'Action', '七杀': 'Order', '正官': 'Order', '偏印': 'Mind', '正印': 'Mind' };
const portraitRow = (god) => { const m = rea17.match(new RegExp(`^\\| The [A-Za-z]+ ${god} \\| ([^|]+) \\|`, 'm')); return m ? m[1].trim() : ''; };
const personaRow = (persona) => { const m = master.match(new RegExp(`^\\| ${persona.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')} \\([^)]*\\) \\| ([^|]+) \\| ([^|]+) \\|`, 'm')); return m ? `Cost dimension: ${m[1].trim()}. Arena: ${m[2].trim()}.` : ''; };
export const godPack = (g) => { const c = J('GOD/' + GOD_FILE[g] + '.json'); return `Persona ${c.persona_name} (${g}). Definition line: "${c.definition_line}". Keyword ${c.keyword}, charge ${c.charge}, poles catalyst ${c.pole_catalyst} / friction ${c.pole_friction}. Family function: ${FAMILY_FN[g]}. ${personaRow(c.persona_name)} Classical portrait: ${portraitRow(g)}. Ruled domains: ${c.domains.join(', ')}. Sibling (other polarity of the family): ${SIB[g]}.`; };
export const GATE_GROUND = { 'Year Gate': 'roots, ancestry, the early world', 'Month Gate': 'work, parents, the chart\'s frame', 'Day Gate': 'the self\'s seat and the spouse palace', 'Hour Gate': 'children, output, late life' };
export const GATE_ERA = { 'Year Gate': 'the Early Chapter (~0–16)', 'Month Gate': 'the Rising Chapter (~16–35)', 'Day Gate': 'the Home Chapter (~35–48, adulthood, the marriage years)', 'Hour Gate': 'the Late Chapter (48+)' };
export const GATE_PEOPLE = { 'Year Gate': 'ancestors and the family\'s name', 'Month Gate': 'parents, siblings, colleagues', 'Day Gate': 'the spouse, the intimate self', 'Hour Gate': 'children, students, heirs' };
export const SEAT_RANK = { month_branch: 'first of seven (月支, the strongest seat)', month_stem: 'second of seven (月干)', day_branch: 'third of seven (日支)', hour_branch: 'fourth of seven (时支)', hour_stem: 'fifth of seven (时干)', year_branch: 'sixth of seven (年支)', year_stem: 'seventh of seven (年干)' };

// ── input packs per axis (facts printed for the generator; target redacted) ──
const q = (s) => JSON.stringify(s);
const missingWide = (pairKey) => `none (self pair): the Body wide gift is cut from this cell's definition_catalyst, echo_of = ${pairKey}.function.definition_catalyst`;
export function stemFacts(stem, { redact = [], pools = false } = {}) {
  const meta = STEMS[stem]; const st = J(`STEM/${meta.file}.json`);
  const show = (k, label = k) => redact.includes(k) ? `- ${label}: [REDACTED: the target field]` : `- ${label}: ${q(st[k])}`;
  let out = `Stem ${stem} ${meta.name}, ${meta.pol === 'yin' ? 'Yin' : 'Yang'} ${meta.el}. Spine: ${meta.spine}. Arena: ${ARENA[meta.el]}.\nAngle Map row: ${angleRow(stem)}\nAngle not to borrow: ${NOT_BORROW[stem] || (['丙', '己', '庚'].includes(stem) ? 'this stem may stand near the recognition axis in its own way only; never another nature\'s cost dimension' : 'not the unwitnessed-martyr angle, which belongs to 丙, 己 and 庚 each differently; write from this stem\'s own row')}.\n${show('manifesto')}\n${show('inscription')}\n${show('dm_overview', 'dm_overview (the sign)')}\n${show('yourNature_desc', 'yourNature_desc (baseline, band-neutral)')}\n- door_note (function → element): ${q(st.door_note)}. ${meta.pol === 'yin' ? 'The yin stem reads carry_yin.excess where the cell carries it.' : 'The yang stem reads carry.excess (no carry_yin).'}`;
  if (pools) for (const [door, en] of Object.entries(st.door_note)) { const key = `${HZ[meta.el]}_${HZ[en]}`; const cell = J(`ELEMENT_PAIR/${key}.json`); const exc = meta.pol === 'yin' && cell.carry_yin?.excess ? { ...cell.carry.excess, ...cell.carry_yin.excess } : cell.carry.excess; out += `\n\n### Pair cell ${key} (door ${door}, ${pairLaw(meta.el, en)})\n- function.definition_catalyst: ${q(cell.function.definition_catalyst)}\n- function.definition_friction: ${q(cell.function.definition_friction)}\n- carry.wide: ${cell.carry.wide ? q(cell.carry.wide) : missingWide(key)}\n- ${meta.pol === 'yin' && cell.carry_yin?.excess ? 'carry_yin.excess' : 'carry.excess'}: ${q(exc)}`; }
  return out;
}
export function bandFacts(stem, band) {
  const meta = STEMS[stem]; const st = J(`STEM/${meta.file}.json`);
  const TERM = { concentrated: 'Overfueled (the core has more than it can channel: the edge never sheathed)', balanced: 'Balanced (the core is fed and drawn when it matters)', open: 'Underfueled (the core burns more than it takes in: the material running low or held back, never a portrait of giving away)' };
  return `Stem ${stem} ${meta.name}, ${meta.pol === 'yin' ? 'Yin' : 'Yang'} ${meta.el}. Spine: ${meta.spine}. Arena: ${ARENA[meta.el]}.\nAngle Map row: ${angleRow(stem)}\nAngle not to borrow: ${NOT_BORROW[stem] || 'not the unwitnessed-martyr angle unless this stem is 丙, 己 or 庚'}.\nBand: ${band} = ${TERM[band]}.\n- manifesto: ${q(st.manifesto)}\n- dm_overview (the sign whose central image sentence 1 must receive): ${q(st.dm_overview)}\n- yourNature_desc (baseline, band-neutral, for the person's trait): ${q(st.yourNature_desc)}`;
}
export function pairCellFacts(key, { redact = [], yin = false } = {}) {
  const [c, e] = key.split('_').map((h) => EL_OF_HZ[h]); const cell = J(`ELEMENT_PAIR/${key}.json`);
  const lines = [`## CELL FACTS\n\nCell ${key}. ${pairLaw(c, e)}`];
  const isRed = (p) => redact.some((r) => p === r || p.startsWith(r + '.'));
  const push = (p, v, label) => lines.push(`- ${label || p}: ${isRed(p) ? '[REDACTED: the target field]' : typeof v === 'string' ? q(v) : q(v)}`);
  push('mechanism.classic', cell.mechanism.classic, 'mechanism.classic (the sourced epigraph)');
  for (const k of ['base', 'catalyst_turn', 'friction_turn']) push(`mechanism.${k}`, cell.mechanism[k]);
  if (yin && cell.mechanism_yin) for (const [k, v] of Object.entries(cell.mechanism_yin)) push(`mechanism_yin.${k}`, v);
  for (const k of ['definition_catalyst', 'definition_friction', 'advise_catalyst', 'advise_friction']) push(`function.${k}`, cell.function[k]);
  push('cta_verdict', cell.cta_verdict);
  for (const [k, v] of Object.entries(cell.carry || {})) push(`carry.${k}`, v);
  if (!cell.carry?.wide) lines.push(`- carry.wide: ${missingWide(key)}`);
  if (yin && cell.carry_yin) for (const [k, v] of Object.entries(cell.carry_yin)) push(`carry_yin.${k}`, v);
  lines.push(`\nThe classical excess idiom for this cell (say it in English in carry.excess, never quote it): ${EXCESS_IDIOM[key]}.`);
  lines.push(`The eight wide openers (a carry.wide clause opens with one; no core repeats one across its wanted energies): ${WIDE_OPENERS.map((o) => `"${o}"`).join(' · ')}.`);
  if (yin) lines.push(`Yin sibling noun set for a _yin target: ${YIN_NOUNS[Object.keys(STEMS).find((s) => STEMS[s].el === c && STEMS[s].pol === 'yin')]}.`);
  lines.push('Fields shown above that are not the target are context for the repetition law (no four-word run shared with them) and for the cut law; do not rewrite them.');
  return lines.join('\n');
}
export function egCellFacts(key, { redact = [], row = null, pole = null } = {}) {
  const [hz, god] = key.split('_'); const el = EL_OF_HZ[hz]; const cell = J(`ELEMENT_GOD/${key}.json`); const sibKey = `${hz}_${SIB[god]}`; const sib = J(`ELEMENT_GOD/${sibKey}.json`);
  const godc = J('GOD/' + GOD_FILE[god] + '.json');
  const isRed = (p) => redact.some((r) => p === r || p.startsWith(r + '.'));
  const lines = [`## CELL FACTS\n\nCell ${key} (${el} carrying ${godc.persona_name}). ${godPack(god)}\nElement arena: ${ARENA[el]}. dm_element (which core reads this cell): ${cell.dm_element}. structural_interaction seed: ${q(cell.structural_interaction)}.`];
  for (const k of ['k2_overview', 'k2_functional', 'adj_chips', 'k2_domain_readings']) lines.push(`- ${k}: ${isRed(k) ? '[REDACTED: the target field]' : q(cell[k])}`);
  if (pole) { const led = cell.fn_reading?.[pole]?.ledger || []; lines.push(`- fn_reading.${pole}.ledger (three rows, index-aligned to adj_chips.${pole}; authored order is significance order):`); led.forEach((r, i) => lines.push(`  - row ${i} "${r.word}": ${row === i && isRed('fn_reading') ? '[REDACTED: the target row]' : q(r.doors)}`)); }
  lines.push(`- Sibling cell ${sibKey} chips (nothing you write may fit the sibling): ${q(sib.adj_chips)}`);
  if (pole && row != null && sib.fn_reading?.[pole]?.ledger?.[row]) lines.push(`- Sibling cell ${sibKey} ${pole} row ${row} trait door, for contrast: ${q(sib.fn_reading[pole].ledger[row].doors.trait)}`);
  else if (!pole) lines.push(`- Sibling cell ${sibKey} k2_overview, for contrast: ${q(sib.k2_overview)}`);
  return lines.join('\n');
}
export function positionFacts(id, { redact = [] } = {}) {
  const pos = J(`POSITION/${id}.json`); const [godFile, ...slotParts] = id.split('_'); const god = GOD_OF_FILE[godFile]; const slot = slotParts.join('_');
  const isRed = (p) => redact.includes(p);
  const lines = [`## CELL FACTS\n\nNamed event: "${pos.term}" · ${pos.term_zh}. ${godPack(god)}\nGate: ${pos.gate} (ground: ${GATE_GROUND[pos.gate]}). Slot kind: ${pos.slot_kind} (${pos.slot_kind === 'stem' ? 'stem = the shown face, "at the Gate"' : 'branch = the root, private, dispositional, "inside the Gate"'}). Era: ${GATE_ERA[pos.gate]}. Relations register: ${GATE_PEOPLE[pos.gate]}. Seat rank: ${SEAT_RANK[slot]}. Declared domains: ${q(pos.domains)}.`];
  for (const k of ['defline', 'teaser', 'reading', 'domain_readings', 'life_chapter', 'relations', 'turn_catalyst', 'turn_friction', 'shadow_line', 'health_line']) lines.push(`- ${k}: ${isRed(k) ? '[REDACTED: the target field]' : q(pos[k])}`);
  return lines.join('\n');
}
export function tgFacts(id, { redact = [] } = {}) {
  const t = J(`TG_PATTERN/${id}.json`); const isRed = (p) => redact.includes(p);
  const sides = t.trigger_gods.map((pair) => pair.map((g) => `${J('GOD/' + GOD_FILE[g] + '.json').persona_name} (${g})`).join(' or ')).join(' × ');
  const lines = [`## CELL FACTS\n\nPattern ${t.name_zh}, "${t.name_en}". Sides: ${sides}. Target domains: ${q(t.target_domains)}. The fused tier applies when both sides share one pillar.`];
  for (const k of ['line', 'reading', 'fused_line']) lines.push(`- ${k}: ${isRed(k) ? '[REDACTED: the target field]' : q(t[k])}`);
  return lines.join('\n');
}

// ── the field registry (one entry per REA_17 §3 card family) ─────────
// Each entry: axis · cards (REA_17 keys) · cell(ctx) resolves the station key
// from the chart or the explicit cell · facts(ctx) · task(ctx) → {ask, shape}
// · original(ctx) · repFields(ctx) → {path: text} the four-gram check runs
// against, with lawful pairs · zone (the B1–B2 reader zone applies) ·
// validate(out, ctx, F, stat). ctx = {cell, state, pole, row, band, chart, yin}.
const pairOf = (ctx) => J(`ELEMENT_PAIR/${ctx.cell}.json`);
const carryOf = (cell, yin) => yin && cell.carry_yin ? Object.fromEntries([...new Set([...Object.keys(cell.carry || {}), ...Object.keys(cell.carry_yin)])].map((k) => [k, { ...(cell.carry?.[k] || {}), ...(cell.carry_yin?.[k] || {}) }])) : (cell.carry || {});
const pairRep = (ctx, except = []) => { const c = pairOf(ctx); const F = {}; for (const k of ['definition_catalyst', 'definition_friction', 'advise_catalyst', 'advise_friction']) F[`function.${k}`] = c.function[k]; for (const k of ['base', 'catalyst_turn', 'friction_turn']) F[`mechanism.${k}`] = c.mechanism[k]; F['cta_verdict'] = c.cta_verdict; for (const [k, v] of Object.entries(c.carry || {})) F[`carry.${k}`] = [v?.clause, v?.remedy].filter(Boolean).join(' '); for (const e of except) delete F[e]; return F; };
const stemRep = (ctx, except = []) => { const st = J(`STEM/${STEMS[ctx.stem].file}.json`); const F = { 'dm_overview': st.dm_overview, 'yourNature_desc': st.yourNature_desc, 'manifesto': st.manifesto, 'inscription': st.inscription }; for (const e of except) delete F[e]; return F; };
