// aliases the CLI accepts
export const FIELD_ALIASES = { 'STEM.gifts': 'STEM.gifts+shadows', 'STEM.shadows': 'STEM.gifts+shadows', 'STEM_BAND.yourNature_desc': 'STEM_BAND.yourNature_desc+self_card', 'STEM_BAND.self_card': 'STEM_BAND.yourNature_desc+self_card', 'ELEMENT_PAIR.mechanism.catalyst_turn': 'ELEMENT_PAIR.mechanism.turn', 'ELEMENT_PAIR.mechanism.friction_turn': 'ELEMENT_PAIR.mechanism.turn', 'ELEMENT_PAIR.function.definition_catalyst': 'ELEMENT_PAIR.function.definition', 'ELEMENT_PAIR.function.definition_friction': 'ELEMENT_PAIR.function.definition', 'ELEMENT_PAIR.function.advise_catalyst': 'ELEMENT_PAIR.function.advise', 'ELEMENT_PAIR.function.advise_friction': 'ELEMENT_PAIR.function.advise', 'ELEMENT_PAIR.function.advise_*': 'ELEMENT_PAIR.function.advise', 'ELEMENT_PAIR.carry': 'ELEMENT_PAIR.carry.pole', 'ELEMENT_GOD.fn_reading': 'ELEMENT_GOD.fn_reading.row', 'POSITION.reading': 'POSITION.reading+teaser+domain_readings', 'POSITION.teaser': 'POSITION.reading+teaser+domain_readings', 'POSITION.domain_readings': 'POSITION.reading+teaser+domain_readings', 'POSITION.turn_catalyst': 'POSITION.turn', 'POSITION.turn_friction': 'POSITION.turn' };

function signNouns(dmOverview) { const stop = new Set(['the', 'is', 'that', 'and', 'it', 'its', 'of', 'in', 'a', 'an', 'to', 'has', 'with', 'for', 'on', 'which', 'what', 'own', 'kind', 'one', 'when', 'who', 'this', 'as', 'by', 'at', 'from', 'yang', 'yin', 'already', 'been', 'through', 'season', 'once', 'only', 'true', 'thing', 'nothing', 'says', 'wall', 'between', 'wars', 'hangs', 'speech', 'agreed', 'personal', 'matter', 'great', 'gone', 'home']); const w = String(dmOverview || '').toLowerCase().replace(/[^a-z\s]/g, ' ').split(/\s+/).filter((x) => x.length > 3 && !stop.has(x)); return [...new Set(w)]; }

function validatePools(out, c, F, stat, gate) {
  const g = out.gifts || [], s = out.shadows || [];
  stat(`shape 7 + 7 (got ${g.length} + ${s.length})`, g.length === 7 && s.length === 7);
  const keys = ['phrase', 'dim', 'door', 'face', 'echo_of', 'desc'];
  stat('every item carries phrase/dim/door/face/echo_of/desc', [...g, ...s].every((it) => keys.every((k) => k in it)));
  const cnt = (a) => a.reduce((m, d) => (m[d] = (m[d] || 0) + 1, m), {});
  const expect = { body: 2, mind: 2, expression: 1, action: 1, order: 1 };
  const same = (a) => JSON.stringify(a, Object.keys(expect).sort()) === JSON.stringify(expect, Object.keys(expect).sort());
  stat(`gift doors ${JSON.stringify(cnt(g.map((x) => x.door)))}`, same(cnt(g.map((x) => x.door))));
  stat(`shadow doors ${JSON.stringify(cnt(s.map((x) => x.door)))}`, same(cnt(s.map((x) => x.door))));
  const fg = cnt(g.map((x) => x.face)), fsd = cnt(s.map((x) => x.face));
  stat(`gift faces ${JSON.stringify(fg)} (expect echo 5, wide 2)`, fg.echo === 5 && fg.wide === 2);
  stat(`shadow faces ${JSON.stringify(fsd)} (expect echo 5, excess 2)`, fsd.echo === 5 && fsd.excess === 2);
  const resolve = (p) => { try { const [cell, ...path] = String(p).split('.'); return get(J(`ELEMENT_PAIR/${cell}.json`), path.join('.')) != null; } catch { return false; } };
  const bad = [...g, ...s].filter((x) => !resolve(x.echo_of)).map((x) => x.echo_of); stat(`echo_of resolves (${bad.length} unresolved${bad.length ? ': ' + bad.slice(0, 3).join(', ') : ''})`, bad.length === 0);
  const IDIOMS = idioms4w();
  for (const [side, arr] of [['gift', g], ['shadow', s]]) arr.forEach((it, i) => {
    const w = `${side}[${i}] ${it.phrase}`;
    const pw = wc(it.phrase); if (pw > 3 && !IDIOMS.has(String(it.phrase).toLowerCase())) F(w, `phrase ${pw} words`);
    if (String(it.phrase).toLowerCase() === String(it.dim).toLowerCase()) F(w, 'phrase = dim');
    if (wc(it.dim) > 3) F(w, 'dim > 3 words');
    gate(w + ' desc', it.desc, P(60));
    const sents = String(it.desc).split(/[.!?]+\s/).filter(Boolean).length; if (sents > 3) F(w, `desc ${sents} sentences`);
    if (/^(The|A) [a-z]+$/.test(String(it.phrase)) && !/\b(ing|s|ed)\b/.test(it.phrase)) F(w, 'bare image phrase ("The + noun")');
  });
  const dg = g.map((x) => String(x.dim).toLowerCase()), ds = s.map((x) => String(x.dim).toLowerCase());
  stat('dims unique within each pool', new Set(dg).size === dg.length && new Set(ds).size === ds.length);
  const all = new Set(); const own = STEMS[c.stem].file + '.json';
  for (const f of fs.readdirSync(S + 'STEM')) if (f.endsWith('.json') && f !== own) { const cc = J('STEM/' + f); [...(cc.gifts || []), ...(cc.shadows || [])].forEach((x) => all.add(String(x.phrase).toLowerCase())); }
  const dup = [...g, ...s].filter((x) => all.has(String(x.phrase).toLowerCase())).map((x) => x.phrase); stat(`phrases unique across the other nine pools (${dup.length} clash${dup.length ? ': ' + dup.join(', ') : ''})`, dup.length === 0);
  const inPool = [...g, ...s].map((x) => String(x.phrase).toLowerCase()); stat('phrases unique within the pool', new Set(inPool).size === inPool.length);
}
function validateTurnCarry(out, c, F, stat, gate) {
  const k = `${c.pole}_turn`; const t = out[k]; gate(k, t, P(35)); stat(`turn opens "${c.pole === 'catalyst' ? 'Run thin,' : 'Run heavy,'}"`, new RegExp(`^Run ${c.pole === 'catalyst' ? 'thin' : 'heavy'},`).test(t || ''));
  const [core, en] = c.cell.split('_').map((h) => EL_OF_HZ[h]);
  const poles = c.pole === 'friction' ? ['friction', 'thin', 'excess'] : ['catalyst', 'missing', ...(core === en ? [] : ['wide'])];
  for (const pole of poles) { const p = out.carry?.[pole]; stat(`carry.${pole} present {clause, remedy}`, !!(p && p.clause && p.remedy)); if (p) { gate(`carry.${pole}.clause`, p.clause, P(18)); gate(`carry.${pole}.remedy`, p.remedy, P(12)); } }
  const p = out.carry?.[c.pole]; if (p && t) { stat('carry clause is cut from the turn', t.toLowerCase().includes(String(p.clause).toLowerCase().replace(/^the /, '').slice(0, 30)) || t.toLowerCase().includes(String(p.clause).toLowerCase().slice(5, 40))); stat('carry remedy is the turn\'s directive', t.toLowerCase().includes(String(p.remedy).toLowerCase().replace(/\.$/, '').slice(0, 25))); }
  const w = out.carry?.wide; if (w) { stat('wide clause opens with one of the eight openers', WIDE_OPENERS.some((op) => String(w.clause || '').startsWith(op.replace('{Element}', en)))); if (/\bdoor\b/i.test(w.clause + ' ' + w.remedy)) F('carry.wide', 'the word "door" never reaches a reader (D4)'); }
  const x = out.carry?.excess; if (x && /[一-鿿]/.test(x.clause + x.remedy)) F('carry.excess', 'the idiom is quoted, not said in English');
}
export function idioms4w() { const m = fs.readFileSync(ROOT + 'Elementum_App/tools/voice-audit.mjs', 'utf8').match(/IDIOMS_4W = new Set\(\[([^\]]+)\]\)/); return new Set(m ? m[1].split(',').map((s) => s.trim().replace(/^'|'$/g, '')) : []); }

// non-blocking channels the validator wires per run: note() = a heuristic stat the read decides,
// readFlag() = a scope or angle question surfaced for the reader.
export const channel = { note: (label, ok) => {}, readFlag: (where, msg) => {} };
const note = (label, ok) => channel.note(label, ok); const readFlag = (where, msg) => channel.readFlag(where, msg);

// ── the mechanical gate (REA_17 §1 audit list; mirrors voice-audit.mjs) ──
export const BANNED = /\b(delve|tapestry|testament|pivotal|crucial|intricate|robust|seamless|foster(ing|s)?|underscores?|showcas(e|ing)|leverag(e|ed)|boasts|vibrant|nestled|profound|realm|unlock|elevate|resonat\w*|navigate|landscape|verdicts?|legitimate|legitimacy|institutional|diligent|exemplary|enterprising|meticulous|destiny|destined|fate|fated|karmic|cosmic|zodiac|astrolog\w*|horoscope|celestial|manifest(ing|s|ed|ation)?|journey|vibration|aligned|empowered|fundamentally|genuinely|in essence|at your core|destined for greatness)\b/i;
export const HEDGE = /\b(often|sometimes|may|tends? to|perhaps)\b/i;
export const BAZI = /\b(Day Master|Ten Gods?|Seven Killings|Direct Officer|Indirect Seal|Direct Seal|Rob Wealth|Food God|Hurt(ing)? Officer|Parallel Self|useful god|favou?rable element|wealth star|Four Pillars|BaZi|Bazi|dayun|liunian|Indirect Wealth|Direct Wealth|Eating God|Friend star)\b/i;
export const PARALLELISM = [/\bnot (?:just |only )?[\w' ]{1,30}?\bbut\b/i, /\bit'?s not\b[^.]{1,40},\s*it'?s\b/i];
export function makeGate(F) {
  return (where, text, { budget, min, youOpen, youOpen3, noYou, theOpen, maxChars } = {}) => {
    const t = String(text || ''); if (!t.trim()) { F(where, 'EMPTY'); return; }
    if (/[—–;→▸•]/.test(t)) F(where, 'sign (em-dash / en-dash / semicolon / arrow / glyph)');
    if (/[一-鿿]/.test(t)) F(where, 'Chinese character');
    const b = t.match(BANNED); if (b) F(where, `banned word "${b[0]}"`);
    const h = t.match(HEDGE); if (h) F(where, `hedge "${h[0]}"`);
    if (/\brooms?\b/i.test(t)) F(where, '"room" (rationed)');
    const z = t.match(BAZI); if (z) F(where, `BaZi label "${z[0]}"`);
    for (const re of PARALLELISM) if (re.test(t)) { F(where, 'negative parallelism'); break; }
    if (/\bYou are someone who\b/.test(t)) F(where, 'hollow opener "You are someone who"');
    const n = wc(t); if (budget && n > budget) F(where, `${n}w > ${budget}w`); if (min && n < min) F(where, `${n}w < ${min}w`);
    if (maxChars && t.length > maxChars) F(where, `${t.length}c > ${maxChars}c`);
    if (youOpen && !/^You(\b|')/.test(t.trim())) F(where, 'does not open on "You"');
    if (youOpen3 && !t.trim().split(/\s+/).slice(0, 3).some((x) => /^you/i.test(x))) F(where, '"you" not within the first three words');
    if (noYou && /\byou(r|rs|rself)?\b/i.test(t)) F(where, 'second person in a third-person field');
    if (theOpen && !t.trim().startsWith(theOpen)) F(where, `does not open with "${theOpen}"`);
  };
}

// ── the within-cell four-gram check (REA_16 §7 repetition law) ───────
const REP_STOP = new Set(['the', 'a', 'an', 'and', 'of', 'to', 'in', 'on', 'it', 'is', 'you', 'your', 'that', 'for', 'with', 'as', 'at', 'by', 'one', 'this']);
export const repGrams = (t) => { const w = String(t || '').toLowerCase().replace(/[^a-z一-鿿\s']/g, ' ').split(/\s+/).filter(Boolean); const out = new Set(); for (let i = 0; i + 4 <= w.length; i++) { const g = w.slice(i, i + 4); if (g.every((x) => REP_STOP.has(x))) continue; out.add(g.join(' ')); } return out; };
export const repShared = (a, b) => { const A = repGrams(a), B = repGrams(b); return [...A].filter((g) => B.has(g)); };
// Lawful echoes (voice-audit.mjs `lawful`): carry ↔ turn, yin ↔ shared, the
// two definitions' templated opener, and a pool item against the pair field
// its echo_of names (the derivation law).
export const lawfulPair = (a, b) => { const t = (x) => x.split('.')[0]; const [ta, tb] = [t(a), t(b)]; return (ta === 'carry' && tb === 'mechanism') || (ta === 'mechanism' && tb === 'carry') || (ta === 'carry' && tb === 'carry') || ta === 'carry_yin' || tb === 'carry_yin' || ta === 'mechanism_yin' || tb === 'mechanism_yin' || (a.startsWith('function.definition_') && b.startsWith('function.definition_')); };
export function fourGramCheck(candidateFields, otherFields, { lawful = lawfulPair, self = true } = {}) {
  const hits = [];
  for (const [cp, ct] of Object.entries(candidateFields)) for (const [op, ot] of Object.entries(otherFields)) {
    if (!ct || !ot || lawful(cp, op)) continue;
    const sh = repShared(ct, ot); if (sh.length) hits.push({ candidate: cp, other: op, gram: sh[0], n: sh.length });
  }
  // within the candidate itself (two fields of one output)
  const keys = self ? Object.keys(candidateFields) : [];
  for (let i = 0; i < keys.length; i++) for (let j = i + 1; j < keys.length; j++) { if (lawful(keys[i], keys[j])) continue; const sh = repShared(candidateFields[keys[i]], candidateFields[keys[j]]); if (sh.length) hits.push({ candidate: keys[i], other: keys[j] + ' (same output)', gram: sh[0], n: sh.length }); }
  return hits;
}
// cross-stem four-gram uniqueness for swap-gram fields (REA_16 §2c)
export function swapGramCheck(text, axis, field, ownFile) {
  const dir = S + axis; const hits = [];
  const mine = repGrams(text);
  for (const f of fs.readdirSync(dir)) { if (!f.endsWith('.json') || f === ownFile || f.startsWith('_')) continue; const v = get(J(`${axis}/${f}`), field); for (const [, t] of flat(v)) { const sh = [...mine].filter((g) => repGrams(t).has(g)); if (sh.length) hits.push({ file: f, gram: sh[0] }); } }
  return hits;
}

// ── the reader zone (B1–B2 on the function page; word level) ─────────
// Zone = the ruled function-page corpus (words the owner already accepted on
// definitions, advice, chips, doors and dot-card lines) ∪ the top-N of a
// public frequency list ∪ the canonical vocabulary. A word outside all three
// is reported; chips block on it, prose blocks past a calibrated rate.
const FREQ_FILE = HERE + '/data/google-10000-english-usa-no-swears.txt';
let FREQ = null; export function freqRank() { if (!FREQ) { FREQ = new Map(); fs.readFileSync(FREQ_FILE, 'utf8').split(/\r?\n/).map((w) => w.trim()).filter(Boolean).forEach((w, i) => { if (!FREQ.has(w)) FREQ.set(w, i + 1); }); } return FREQ; }
export const ZONE_TIER = { core: 3000, edge: 6000 };
const CANON = new Set(['wood', 'fire', 'earth', 'metal', 'water', 'body', 'mind', 'expression', 'action', 'order', 'core', 'catalyst', 'friction', 'overfueled', 'balanced', 'underfueled', 'channel', 'refill', 'oak', 'vine', 'sun', 'candle', 'mountain', 'field', 'blade', 'jewel', 'ocean', 'rain', 'twin', 'rival', 'artisan', 'virtuoso', 'horizon', 'steward', 'general', 'magistrate', 'alchemist', 'sage', 'wealth', 'health', 'career', 'love', 'family', 'social', 'growth', 'gate', 'chapter', 'energy', 'elementum']);
const lemmas = (w) => { const out = [w]; const push = (x) => { if (x.length >= 2 && !out.includes(x)) out.push(x); }; if (w.endsWith('ies')) push(w.slice(0, -3) + 'y'); if (w.endsWith('ied')) push(w.slice(0, -3) + 'y'); if (w.endsWith('es')) push(w.slice(0, -2)); if (w.endsWith('s')) push(w.slice(0, -1)); if (w.endsWith('ed')) { push(w.slice(0, -2)); push(w.slice(0, -1)); if (w.length > 4 && w[w.length - 3] === w[w.length - 4]) push(w.slice(0, -3)); } if (w.endsWith('ing')) { push(w.slice(0, -3)); push(w.slice(0, -3) + 'e'); if (w.length > 5 && w[w.length - 4] === w[w.length - 5]) push(w.slice(0, -4)); } if (w.endsWith('ly')) { push(w.slice(0, -2)); if (w.endsWith('ily')) push(w.slice(0, -3) + 'y'); } if (w.endsWith('er')) { push(w.slice(0, -2)); push(w.slice(0, -1)); } if (w.endsWith('est')) push(w.slice(0, -3)); if (w.endsWith('ness')) push(w.slice(0, -4)); if (w.endsWith('ful')) push(w.slice(0, -3)); if (w.endsWith('less')) push(w.slice(0, -4)); if (w.startsWith('un') || w.startsWith('re')) push(w.slice(2)); if (w.startsWith('over')) push(w.slice(4)); if (w.endsWith("n't")) push(w.slice(0, -3)); return out; };
export const zoneTokens = (t) => String(t || '').toLowerCase().replace(/[’‘]/g, "'").replace(/'(s|re|ve|ll|d|m)\b/g, '').replace(/n't\b/g, ' not').replace(/[^a-z'\-\s]/g, ' ').split(/[\s\-]+/).map((w) => w.replace(/^'+|'+$/g, '')).filter((w) => w.length > 1);
let ZONE_CORPUS = null;
// The ruled function-page corpus: every word already shipping on the zone's
// surfaces (REA_16 §2c THE VOCABULARY ZONE: cta_verdict, definitions, advises,
// adj_chips, fn_reading doors; k2_functional per its card).
export function zoneCorpus() {
  if (ZONE_CORPUS) return ZONE_CORPUS; ZONE_CORPUS = new Set();
  const add = (t) => zoneTokens(t).forEach((w) => ZONE_CORPUS.add(w));
  for (const f of fs.readdirSync(S + 'ELEMENT_PAIR')) if (f.endsWith('.json')) { const c = J('ELEMENT_PAIR/' + f); for (const k of ['definition_catalyst', 'definition_friction', 'advise_catalyst', 'advise_friction']) add(c.function?.[k]); add(c.cta_verdict); }
  for (const f of fs.readdirSync(S + 'ELEMENT_GOD')) if (f.endsWith('.json')) { const c = J('ELEMENT_GOD/' + f); for (const [, t] of flat(c.adj_chips)) add(t); for (const [, t] of flat(c.fn_reading)) add(t); add(c.k2_functional); }
  return ZONE_CORPUS;
}
export function zoneCheck(text, { corpus = zoneCorpus() } = {}) {
  const rank = freqRank(); const words = zoneTokens(text); const out = { total: words.length, outside: [], edge: [] }; const seen = new Set();
  for (const w of words) {
    if (seen.has(w)) continue; seen.add(w);
    if (CANON.has(w) || /^\d/.test(w)) continue;
    const ls = lemmas(w); const r = Math.min(...ls.map((l) => rank.get(l) || Infinity));
    const inCorpus = ls.some((l) => corpus.has(l));
    if (r <= ZONE_TIER.core || inCorpus) continue;
    if (r <= ZONE_TIER.edge) out.edge.push(`${w} (rank ${r})`); else out.outside.push(r === Infinity ? w : `${w} (rank ${r})`);
  }
  return out;
}
// Calibration: the rate of outside-zone words the shipping function-page
// prose reaches when each field is scored against the corpus MINUS itself
// (leave-one-out), so the threshold is what the ruled corpus itself tolerates.
export function zoneCalibrate() {
  const rates = []; const rank = freqRank();
  const texts = [];
  for (const f of fs.readdirSync(S + 'ELEMENT_PAIR')) if (f.endsWith('.json')) { const c = J('ELEMENT_PAIR/' + f); for (const k of ['definition_catalyst', 'definition_friction', 'advise_catalyst', 'advise_friction']) texts.push([`ELEMENT_PAIR/${f} ${k}`, c.function?.[k]]); texts.push([`ELEMENT_PAIR/${f} cta_verdict`, c.cta_verdict]); }
  for (const f of fs.readdirSync(S + 'ELEMENT_GOD')) if (f.endsWith('.json')) { const c = J('ELEMENT_GOD/' + f); for (const [p, t] of flat(c.fn_reading)) if (/doors/.test(p)) texts.push([`ELEMENT_GOD/${f} ${p}`, t]); }
  const counts = new Map(); for (const [, t] of texts) for (const w of new Set(zoneTokens(t))) counts.set(w, (counts.get(w) || 0) + 1);
  for (const [where, t] of texts) { const words = zoneTokens(t); let outside = 0; const seen = new Set(); for (const w of words) { if (seen.has(w) || CANON.has(w)) continue; seen.add(w); const ls = lemmas(w); const r = Math.min(...ls.map((l) => rank.get(l) || Infinity)); const elsewhere = ls.some((l) => (counts.get(l) || 0) > (l === w ? 1 : 0)); if (r > ZONE_TIER.edge && !elsewhere) outside++; } rates.push({ where, words: words.length, outside, per100: words.length ? +(100 * outside / words.length).toFixed(2) : 0 }); }
  rates.sort((a, b) => b.per100 - a.per100); return rates;
}
export const ZONE_BLOCK_PER100 = 14; // from zoneCalibrate() at head 06e38605: the ruled corpus reaches 13.64 per 100 under leave-one-out (see README)
